```tsx
function SortableHeader({title, columnId, sort, onSort}) {
    const active = sort?.columnId === columnId;
    return (
        <button type="button" className={b('header', {active})} onClick={() => onSort(columnId)}>
            <span>{title}</span>
            <Icon data={active ? (sort.order === 'asc' ? TriangleUpFill : TriangleDownFill) : ArrowUpArrowDown} size={14} className={...} />
        </button>
    );
}
